(()=>{'use strict';if(window.GSVisualRuntimeV4)return;
function resize(el){if(!(el instanceof HTMLTextAreaElement)||!el.getClientRects().length)return;el.rows=1;el.dataset.gsAutosize='true';const top=el.scrollTop;el.style.height='auto';const css=getComputedStyle(el),border=parseFloat(css.borderTopWidth)+parseFloat(css.borderBottomWidth);el.style.height=Math.ceil(el.scrollHeight+border)+'px';el.scrollTop=top}
const widths=new WeakMap(),observed=new WeakSet(),observer=window.ResizeObserver?new ResizeObserver(entries=>{for(const {target,contentRect} of entries){const width=contentRect.width;if(widths.get(target)!==width){widths.set(target,width);resize(target)}}}):null;
function organizeHeads(){for(const head of document.querySelectorAll('main .view>.page-head,#hrContent>.page-head,.finance-workspace>.page-head')){if(head.contains(document.activeElement))continue;let heading=[...head.children].find(x=>x.matches('h1,h2,h3')||x.querySelector('h1,h2,h3'));if(!heading)continue;if(heading.matches('h1,h2,h3')){const group=document.createElement('div');group.className='gs-page-heading';heading.before(group);const description=heading.nextElementSibling;group.append(heading);if(description?.matches('p'))group.append(description);heading=group}let actions=head.querySelector(':scope>.gs-page-actions');const nodes=[...head.children].filter(x=>x!==heading&&x!==actions);if(!nodes.length)continue;if(!actions){actions=document.createElement('div');actions.className='gs-page-actions';head.append(actions)}for(const node of nodes)actions.append(node)}}
let queued=false;function refresh(){if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;window.WorkspaceShellV4?.refreshHeaderChrome?.();organizeHeads();document.querySelectorAll('textarea').forEach(el=>{if(observer&&!observed.has(el)){observed.add(el);observer.observe(el)}resize(el)})})}
document.addEventListener('input',e=>resize(e.target),true);document.addEventListener('compositionend',e=>resize(e.target),true);document.addEventListener('toggle',refresh,true);window.addEventListener('resize',refresh);document.addEventListener('gs:view-changed',refresh);
function appearance(){if(window.WorkspaceShellV4||document.getElementById('standaloneThemeToggle'))return;let key='gs-v4-theme';try{const id=JSON.parse(localStorage.getItem('grupo_saude_v4_demo_2')||'{}').currentUser;if(id)key='gs-v4-theme:'+encodeURIComponent(String(id));document.documentElement.dataset.theme=(localStorage.getItem(key)||localStorage.getItem('gs-v4-theme'))==='dark'?'dark':'light'}catch{}const button=document.createElement('button');button.type='button';button.id='standaloneThemeToggle';button.className='icon-btn standalone-theme-toggle';button.textContent='◐';button.setAttribute('aria-label','Alternar modo claro e escuro');const sync=()=>button.setAttribute('aria-pressed',String(document.documentElement.dataset.theme==='dark'));button.addEventListener('click',()=>{const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;try{localStorage.setItem(key,theme)}catch{}sync()});sync();const host=document.querySelector('.top-actions')||document.querySelector('main')||document.body;host.prepend(button)}
function boot(){appearance();new MutationObserver(refresh).observe(document.body,{childList:true,subtree:true});refresh()}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();window.GSVisualRuntimeV4={resize,refresh,organizeHeads};})();
